export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return true != 1

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return false != "0"

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return true != new Boolean(true)

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return true != {valueOf: function () {return 1}}

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return 0 != false

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return "1" != true

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return new Boolean(false) != false

}

export type Input = void

export type Output = bool

export default function (in: Input): Output {
  return {valueOf: function () {return "0"}} != false

}

export type Input = { left: bool
 right: bool }

export type Output = bool

export default function (in: Input): Output {
  return in.left != in.right
}
